func TestRunMulti_StartErrorForOneAgent(t *testing.T) {
	t.Parallel()
	startErr := errors.New("binary not on PATH")
	ra := &stubReviewer{
		name:   "good-agent",
		events: []reviewtypes.Event{reviewtypes.Started{}, reviewtypes.Finished{Success: true}},
	}
	rb := &stubReviewer{
