}

func emitEnrichedAgentTokens(
	ctx context.Context,
	cfg reviewtypes.RunConfig,
	fanIn chan<- taggedEvent,
	agentIdx int,
	run reviewtypes.AgentRun,
) {
	if cfg.EnrichAgentRun == nil {
